import json, os, math
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
def B(en, vi=None): return dict(en=en, vi=vi if vi is not None else en)
def O(opts): return [B(*o) if isinstance(o, tuple) else B(o) for o in opts]
T = dict(basic=B('Op-amp basics', 'Khái niệm op-amp'), mode=B('Input modes and CMRR', 'Chế độ ngõ vào và CMRR'),
         spec=B('Offset, bias and slew rate', 'Dòng/áp offset, dòng phân cực và slew rate'), fb=B('Negative feedback and gain', 'Hồi tiếp âm và hệ số khuếch đại'),
         imp=B('Impedances and compensation', 'Trở kháng và bù'), freq=B('Frequency response and bandwidth', 'Đáp ứng tần số và băng thông'))
items = []
def mcq(n, pg, en, vi, opts, c, xe, xv, topic, lvl=1, fixed=False):
    items.append(dict(kind='mcq', q=B(en, vi), opts=O(opts), correct=c, explain=B(xe, xv), level=lvl, topic=T[topic],
        src=B(f'Floyd 9e, Ch.12, Self-Test Q{n} (p.{pg})', f'Floyd 9e, Ch.12, Self-Test câu {n} (tr.{pg})'), origin='goc', fixed_order=fixed,
        check='chapter text + script'))
